const int _demod_a3_noti_table_num = sizeof(_demod_a3_noti_table) / sizeof(demod_a3_noti_ctrl_t);

#ifdef _L1_TABLE_VALIDATION
static demod_a3_noti_ctrl_t _check_a3_noti_table[10000];
#endif

int DEMOD_L1_TABLE_Update (LX_DEMOD_L1_Context * core) {
	int ret = 0;

	UINT8 * ddr_addr = NULL;
	UINT8 * ret_addr = NULL;

	UINT32 table_offset = (DDR_A3_NOTI_TABLE_BASE - DDR_ADDR_START);
	UINT32 table_size = (DDR_A3_NOTI_TABLE_LAST - DDR_A3_NOTI_TABLE_BASE + 4);

	ddr_addr = (UINT8 *)vmap_phys(gMemCfgDEMOD_FW.memory_base + table_offset, table_size);
	DEMOD_DEBUG("vmap_phys, 0x%08X, 0x%x => addr %p\n", gMemCfgDEMOD_FW.memory_base + table_offset, table_size, ddr_addr);
	if(!ddr_addr) {
		DEMOD_ERROR("vmap_phys fail!!!\n");
		return RET_ERROR;
	}

	DEMOD_INFO("table update @0x%08x, size %lu, cnt %d\n", gMemCfgDEMOD_FW.memory_base + table_offset, sizeof(_demod_a3_noti_table), _demod_a3_noti_table_num);

	ret_addr = memcpy(ddr_addr, _demod_a3_noti_table, sizeof(_demod_a3_noti_table));
	DEMOD_NOTI("table update done, ret %p\n", ret_addr);

#ifdef _L1_TABLE_VALIDATION
	memset(_check_a3_noti_table, 0, sizeof(_check_a3_noti_table));
	ret_addr = memcpy(_check_a3_noti_table, ddr_addr, sizeof(_check_a3_noti_table));
	DEMOD_NOTI("read ret %p\n", ret_addr);

	{
		int i;
		for (i = 0; i < 10000; i++) {
			ret = memcmp(&_demod_a3_noti_table[i], &_check_a3_noti_table[i], sizeof(demod_a3_noti_ctrl_t));
			if (ret != 0)
			{
				DEMOD_NOTI("%d diff, %x,... - %x,..., ret %d\n", i,
					_demod_a3_noti_table[i].offset, _check_a3_noti_table[i].offset,
					ret);
			}
		}
		DEMOD_NOTI("compare done %d\n", i);
	}
#endif

	vunmap_phys(ddr_addr);
	return NO_DEMOD_ERROR;
}
#endif
